/* Simplified from bash initialize_shell_variables(), pre-patch. */
void initialize_shell_variables(char **env)
{
    char *name, *string;
    int string_length;

    for (int i = 0; env[i]; i++)
    {
        name = savestring(env[i]);
        string = strchr(name, '=');
        if (string == 0)
            continue;
        *string++ = '\0';               /* split NAME=VALUE */
        string_length = strlen(string);

        /* If the value looks like a function definition, import it. */
        if (STREQN("() {", string, 4))
        {
            char *expr = (char *)xmalloc(3 + strlen(name) + string_length);
            sprintf(expr, "%s %s", name, string);

            /* Parse and run the string to define the function. */
            parse_and_execute(expr, name, SEVAL_NOHIST);
        }
    }
}

